import run.halo.app.extension.router.SortableRequest;
import run.halo.app.infra.exception.UnsatisfiedAttributeValueException;

@Component
@RequiredArgsConstructor
public class UserEndpoint implements CustomEndpoint {

    private static final String[] ALLOWED_AVATAR_EXTENSIONS = new String[] {"png", "jpg", "jpeg", "gif"};

    private final UserConsoleService userConsoleService;

    @Override
    public RouterFunction<ServerResponse> endpoint() {
        var tag = "UserV1alpha1Console";
        return SpringdocRouteBuilder.route()
                .GET(
                        "/users/-",
                        userConsoleService::me,
                        builder -> builder.operationId("GetCurrentUserDetail")
                                .description("""
                                        Get current user detail.
                                        Deprecated in favor of GET /apis/uc.api.halo.run/v1alpha1/users/-.""")
                                .deprecated(true)
                                .tag(tag)
                                .response(responseBuilder().implementation(DetailedUser.class)))
                .GET(
                        "/users/{name}",
                        userConsoleService::getUserByName,
                        builder -> builder.operationId("GetUserDetail")
                                .description("Get user detail by metadata.name")
                                .tag(tag)
                                .parameter(parameterBuilder()
                                        .in(ParameterIn.PATH)
                                        .name("name")
                                        .description("User metadata.name")
                                        .required(true))
                                .response(responseBuilder().implementation(DetailedUser.class)))
                .PUT(
                        "/users/-",
                        userConsoleService::updateProfile,
                        builder -> builder.operationId("UpdateCurrentUser")
                                .description("""
                                        Update current user profile.
                                        Deprecated in favor of PUT /apis/uc.api.halo.run/v1alpha1/users/-.""")
                                .deprecated(true)
                                .tag(tag)
                                .requestBody(requestBodyBuilder()
                                        .required(true)
                                        .implementation(UpdateMyProfileRequest.class))
                                .response(responseBuilder().implementation(User.class)))
                .PUT(
                        "/users/{name}",
                        userConsoleService::updateUserProfile,
                        builder -> builder.operationId("UpdateUserProfile")
                                .description("Update user profile without changing credentials or roles.")
                                .tag(tag)
                                .parameter(parameterBuilder()
                                        .in(ParameterIn.PATH)
                                        .name("name")
                                        .required(true))
                                .requestBody(requestBodyBuilder()
                                        .required(true)
                                        .implementation(UpdateUserProfileRequest.class))
                                .response(responseBuilder().implementation(User.class)))
                .POST(
                        "/users/{name}/permissions",
                        userConsoleService::grantPermission,
                        builder -> builder.operationId("GrantPermission")
                                .description("Grant permissions to user")
                                .tag(tag)
                                .parameter(parameterBuilder()
                                        .in(ParameterIn.PATH)
                                        .name("name")
                                        .description("User metadata.name")
                                        .required(true))
                                .requestBody(requestBodyBuilder().required(true).implementation(GrantRequest.class))
                                .response(responseBuilder().implementation(User.class)))
                .POST(
                        "/users",
                        userConsoleService::createUser,
                        builder -> builder.operationId("CreateUser")
                                .description("Creates a new user.")
                                .tag(tag)
                                .requestBody(
                                        requestBodyBuilder().required(true).implementation(CreateUserRequest.class))
                                .response(responseBuilder().implementation(User.class)))
                .GET(
                        "/users/{name}/permissions",
                        userConsoleService::getUserPermission,
                        builder -> builder.operationId("GetPermissions")
                                .description("""
                                        Get permissions of a user by metadata.name.
                                        For the current user, prefer GET /apis/uc.api.halo.run/v1alpha1/users/-/permissions.""")
                                .tag(tag)
                                .parameter(parameterBuilder()
                                        .in(ParameterIn.PATH)
                                        .name("name")
                                        .description("User metadata.name")
                                        .required(true))
                                .response(responseBuilder().implementation(UserPermission.class)))
                .PUT(
                        "/users/-/password",
                        userConsoleService::changeOwnPassword,
                        builder -> builder.operationId("ChangeOwnPassword")
                                .description("""
                                        Change own password of user.
                                        Deprecated in favor of PUT /apis/uc.api.halo.run/v1alpha1/users/-/password.""")
                                .deprecated(true)
                                .tag(tag)
                                .requestBody(requestBodyBuilder()
                                        .required(true)
                                        .implementation(ChangeOwnPasswordRequest.class))
                                .response(responseBuilder().implementation(User.class)))
                .PUT(
                        "/users/{name}/password",
                        userConsoleService::changeAnyonePasswordForAdmin,
                        builder -> builder.operationId("ChangeAnyonePassword")
                                .description("Change anyone password of user for admin.")
                                .tag(tag)
                                .parameter(parameterBuilder()
                                        .in(ParameterIn.PATH)
                                        .name("name")
                                        .description(
                                                "User metadata.name. If the name is equal to '-', it will change the "
                                                        + "password of current user.")
                                        .required(true))
                                .requestBody(
                                        requestBodyBuilder().required(true).implementation(ChangePasswordRequest.class))
                                .response(responseBuilder().implementation(User.class)))
                .GET("users", userConsoleService::list, builder -> {
                    builder.operationId("ListUsers")
                            .tag(tag)
                            .description("List users")
                            .response(responseBuilder().implementation(generateGenericClass(ListedUser.class)));
                    ListRequest.buildParameters(builder);
                })
                .POST(
                        "users/{name}/avatar",
                        contentType(MediaType.MULTIPART_FORM_DATA),
                        userConsoleService::uploadUserAvatar,
                        builder -> builder.operationId("UploadUserAvatar")
                                .description("""
                                        Upload a user's avatar by metadata.name.
                                        For the current user, prefer POST /apis/uc.api.halo.run/v1alpha1/users/-/avatar.""")
                                .tag(tag)
                                .parameter(parameterBuilder()
                                        .in(ParameterIn.PATH)
                                        .name("name")
                                        .description("User metadata.name")
                                        .required(true))
                                .requestBody(requestBodyBuilder()
                                        .required(true)
                                        .content(contentBuilder()
                                                .mediaType(MediaType.MULTIPART_FORM_DATA_VALUE)
                                                .schema(schemaBuilder().implementation(IAvatarUploadRequest.class))))
                                .response(responseBuilder().implementation(User.class)))
                .DELETE(
                        "users/{name}/avatar",
                        userConsoleService::deleteUserAvatar,
                        builder -> builder.tag(tag)
                                .operationId("DeleteUserAvatar")
                                .description("""
                                        Delete a user's avatar by metadata.name.
                                        For the current user, prefer DELETE /apis/uc.api.halo.run/v1alpha1/users/-/avatar.""")
                                .parameter(parameterBuilder()
                                        .in(ParameterIn.PATH)
                                        .name("name")
                                        .description("User metadata.name")
                                        .required(true))
                                .response(responseBuilder().implementation(User.class))
                                .build())
                .POST(
                        "users/-/send-email-verification-code",
                        userConsoleService::sendEmailVerificationCode,
                        builder -> builder.tag(tag)
                                .deprecated(true)
                                .operationId("SendEmailVerificationCode")
                                .requestBody(requestBodyBuilder()
                                        .implementation(EmailVerifyRequest.class)
                                        .required(true))
                                .description("Send email verification code for user")
                                .response(responseBuilder().implementation(Void.class))
                                .build())
                .POST(
                        "users/-/verify-email",
                        userConsoleService::verifyEmail,
                        builder -> builder.tag(tag)
                                .deprecated(true)
                                .operationId("VerifyEmail")
                                .description("Verify email for user by code.")
                                .requestBody(
                                        requestBodyBuilder().required(true).implementation(VerifyCodeRequest.class))
                                .response(responseBuilder().implementation(Void.class))
                                .build())
                .build();
    }

    /**
     * Payload for sending an email verification code.
     *
     * @param email email address to verify
     */
    public record EmailVerifyRequest(
            @Schema(requiredMode = REQUIRED) @Email @NotBlank
            String email) {}

    /**
     * Payload for verifying an email address by code.
     *
     * @param password current password of the authenticated user
     * @param code email verification code
     */
    public record VerifyCodeRequest(
            @Schema(requiredMode = REQUIRED) String password,

            @Schema(requiredMode = REQUIRED, minLength = 1) String code) {}

    /** Multipart payload for uploading a user avatar. */
    @Schema(types = "object")
    public interface IAvatarUploadRequest {
        /** Avatar file. */
        @Schema(requiredMode = REQUIRED)
        FilePart getFile();
    }

    public record AvatarUploadRequest(MultiValueMap<String, Part> formData) {
        public FilePart getFile() {
            Part file = formData.getFirst("file");
            if (file == null) {
                throw new ServerWebInputException("No file part found in the request");
            }

            if (!(file instanceof FilePart filePart)) {
                throw new ServerWebInputException("Invalid part of file");
            }

            boolean isNoneExt = Arrays.stream(ALLOWED_AVATAR_EXTENSIONS)
                    .noneMatch(ext -> filePart.filename().endsWith("." + ext));

            if (isNoneExt) {
                throw new ServerWebInputException(
                        "Only support file with extension: " + String.join(", ", ALLOWED_AVATAR_EXTENSIONS));
            }
            return filePart;
        }
    }

    record UpdateUserProfileRequest(
            @Schema(requiredMode = REQUIRED) String displayName,
            @Schema(requiredMode = REQUIRED) String email,
            String avatar,
            String phone,
            String bio,
            Map<String, String> annotations) {}

    /**
     * Payload for creating a user from the console.
     *
     * @param name user {@code metadata.name}, which also serves as the login name
     * @param email email address of the user
     * @param displayName display name shown in the console and theme
     * @param avatar avatar URL of the user
     * @param phone phone number of the user
     * @param password raw password to set for the user
     * @param bio biography or profile text of the user
     * @param annotations metadata annotations to set on the user
     */
    record CreateUserRequest(
            @Schema(requiredMode = REQUIRED) String name,

            @Schema(requiredMode = REQUIRED) String email,

            String displayName,

            String avatar,

            String phone,

            String password,

            String bio,

            Map<String, String> annotations) {

        /**
         * Creates a new user from {@link CreateUserRequest}. Note: this method will not set password.
         *
         * @param userRequest user request
         * @return user from request
         */
        public static User from(CreateUserRequest userRequest) {
            var user = new User();
            user.setMetadata(new Metadata());
            user.getMetadata().setName(userRequest.name());
            user.getMetadata().setAnnotations(new HashMap<>());
            Map<String, String> annotations = defaultIfNull(userRequest.annotations(), Map.of());
            user.getMetadata().getAnnotations().putAll(annotations);

            var spec = new User.UserSpec();
            user.setSpec(spec);
            spec.setEmail(userRequest.email());
            spec.setDisplayName(defaultIfBlank(userRequest.displayName(), userRequest.name()));
            spec.setAvatar(userRequest.avatar());
            spec.setPhone(userRequest.phone());
            spec.setBio(userRequest.bio());
            return user;
        }
    }

    /**
     * Payload for updating the current user's editable profile fields.
     *
     * @param displayName display name shown in the console and theme
     * @param bio biography or profile text
     */
    public record UpdateMyProfileRequest(
            @Schema(requiredMode = REQUIRED) String displayName, String bio) {}

    /**
     * Payload for changing the current user's password.
     *
     * @param oldPassword old password
     * @param password new password
     */
    record ChangeOwnPasswordRequest(
            @Schema(requiredMode = REQUIRED) String oldPassword,

            @Schema(requiredMode = REQUIRED, minLength = 5) String password) {

        public ChangeOwnPasswordRequest {
            if (password == null || password.length() < 5 || password.length() > 257) {
                throw new UnsatisfiedAttributeValueException(
                        "password is required.", "validation.error.password.size", new Object[] {5, 257});
            }
        }
    }

    /**
     * Payload for changing a user's password.
     *
     * @param password new password
     */
    record ChangePasswordRequest(
            @Schema(requiredMode = REQUIRED, minLength = 5) String password) {}

    /**
     * User detail response with resolved roles.
     *
     * @param user user extension
     * @param roles roles granted to the user
     * @param impersonator name of the original administrator who switched to this user, or {@code null} if the current
     *     session is not impersonated
     * @param passwordSet whether the user has a password set; {@code null} when the response is not the current user's
     *     own detail
     */
    public record DetailedUser(
            @Schema(requiredMode = REQUIRED) User user,

            @Schema(requiredMode = REQUIRED) List<Role> roles,

            String impersonator,

            Boolean passwordSet) {

        public DetailedUser(User user, List<Role> roles, String impersonator) {
            this(user, roles, impersonator, null);
        }
    }

    /**
     * Payload for granting roles to a user.
     *
     * @param roles role {@code metadata.name} values to grant
     */
    record GrantRequest(@Schema(requiredMode = REQUIRED) Set<String> roles) {}

    /** Resolved role and permission information for a user. */
    @Data
    public static class UserPermission {
        /** Roles granted to the user. */
        @Schema(requiredMode = REQUIRED)
        private List<Role> roles;

        /** Role templates or permissions resolved from granted roles. */
        @Schema(requiredMode = REQUIRED)
        private List<Role> permissions;

        /** Resolved UI permission identifiers. */
        @Schema(requiredMode = REQUIRED)
        private List<String> uiPermissions;
    }

    public static class ListRequest extends SortableRequest {

        public ListRequest(ServerRequest request) {
            super(request.exchange());
        }

        @Schema(name = "keyword")
        public String getKeyword() {
            return queryParams.getFirst("keyword");
        }

        @Schema(name = "role")
        public String getRole() {
            return queryParams.getFirst("role");
        }

        /** Converts query parameters to list options. */
        public ListOptions toListOptions() {
            var defaultListOptions = labelAndFieldSelectorToListOptions(getLabelSelector(), getFieldSelector());

            var builder = ListOptions.builder(defaultListOptions);

            Optional.ofNullable(getKeyword())
                    .filter(StringUtils::isNotBlank)
                    .ifPresent(keyword -> builder.andQuery(or(
                            equal("spec.email", keyword),
                            contains("spec.displayName", keyword),
                            equal("metadata.name", keyword))));

            Optional.ofNullable(getRole())
                    .filter(StringUtils::isNotBlank)
                    .ifPresent(role -> builder.andQuery(in(User.USER_RELATED_ROLES_INDEX, role)));

            return builder.build();
        }

        public static void buildParameters(Builder builder) {
            SortableRequest.buildParameters(builder);
            builder.parameter(parameterBuilder()
                            .in(ParameterIn.QUERY)
                            .name("keyword")
                            .description("Keyword to search")
                            .implementation(String.class)
                            .required(false))
                    .parameter(parameterBuilder()
                            .in(ParameterIn.QUERY)
                            .name("role")
                            .description("Role metadata.name")
                            .implementation(String.class)
