     * @param phone phone number of the user
     * @param password raw password to set for the user
     * @param bio biography or profile text of the user
     * @param annotations metadata annotations to set on the user
     */
    record CreateUserRequest(
            @Schema(requiredMode = REQUIRED) String name,

            @Schema(requiredMode = REQUIRED) String email,

            String displayName,

            String avatar,

            String phone,

            String password,

            String bio,

            Map<String, String> annotations) {

        /**
         * Creates a new user from {@link CreateUserRequest}. Note: this method will not set password.
         *
         * @param userRequest user request
         * @return user from request
         */
        public static User from(CreateUserRequest userRequest) {
            var user = new User();
            user.setMetadata(new Metadata());
            user.getMetadata().setName(userRequest.name());
            user.getMetadata().setAnnotations(new HashMap<>());
            Map<String, String> annotations = defaultIfNull(userRequest.annotations(), Map.of());
            user.getMetadata().getAnnotations().putAll(annotations);

            var spec = new User.UserSpec();
            user.setSpec(spec);
            spec.setEmail(userRequest.email());
            spec.setDisplayName(defaultIfBlank(userRequest.displayName(), userRequest.name()));
            spec.setAvatar(userRequest.avatar());
            spec.setPhone(userRequest.phone());
            spec.setBio(userRequest.bio());
            return user;
        }
    }

    /**
     * Payload for updating the current user's editable profile fields.
     *
     * @param displayName display name shown in the console and theme
     * @param bio biography or profile text
     */
    public record UpdateMyProfileRequest(
            @Schema(requiredMode = REQUIRED) String displayName, String bio) {}

    /**
     * Payload for changing the current user's password.
     *
     * @param oldPassword old password
     * @param password new password
     */
    record ChangeOwnPasswordRequest(
            @Schema(requiredMode = REQUIRED) String oldPassword,

            @Schema(requiredMode = REQUIRED, minLength = 5) String password) {

        public ChangeOwnPasswordRequest {
            if (password == null || password.length() < 5 || password.length() > 257) {
                throw new UnsatisfiedAttributeValueException(
                        "password is required.", "validation.error.password.size", new Object[] {5, 257});
            }
        }
    }

    /**
     * Payload for changing a user's password.
     *
     * @param password new password
     */
    record ChangePasswordRequest(
            @Schema(requiredMode = REQUIRED, minLength = 5) String password) {}

    /**
     * User detail response with resolved roles.
     *
     * @param user user extension
     * @param roles roles granted to the user
     * @param impersonator name of the original administrator who switched to this user, or {@code null} if the current
     *     session is not impersonated
     * @param passwordSet whether the user has a password set; {@code null} when the response is not the current user's
     *     own detail
     */
    public record DetailedUser(
            @Schema(requiredMode = REQUIRED) User user,

            @Schema(requiredMode = REQUIRED) List<Role> roles,

            String impersonator,

            Boolean passwordSet) {

        public DetailedUser(User user, List<Role> roles, String impersonator) {
            this(user, roles, impersonator, null);
        }
    }

    /**
     * Payload for granting roles to a user.
     *
     * @param roles role {@code metadata.name} values to grant
     */
    record GrantRequest(@Schema(requiredMode = REQUIRED) Set<String> roles) {}

    /** Resolved role and permission information for a user. */
    @Data
    public static class UserPermission {
        /** Roles granted to the user. */
        @Schema(requiredMode = REQUIRED)
        private List<Role> roles;

        /** Role templates or permissions resolved from granted roles. */
        @Schema(requiredMode = REQUIRED)
        private List<Role> permissions;

        /** Resolved UI permission identifiers. */
        @Schema(requiredMode = REQUIRED)
        private List<String> uiPermissions;
    }

    public static class ListRequest extends SortableRequest {

        public ListRequest(ServerRequest request) {
            super(request.exchange());
        }

        @Schema(name = "keyword")
        public String getKeyword() {
            return queryParams.getFirst("keyword");
        }

        @Schema(name = "role")
        public String getRole() {
            return queryParams.getFirst("role");
        }

        /** Converts query parameters to list options. */
        public ListOptions toListOptions() {
            var defaultListOptions = labelAndFieldSelectorToListOptions(getLabelSelector(), getFieldSelector());

            var builder = ListOptions.builder(defaultListOptions);

            Optional.ofNullable(getKeyword())
                    .filter(StringUtils::isNotBlank)
                    .ifPresent(keyword -> builder.andQuery(or(
                            equal("spec.email", keyword),
                            contains("spec.displayName", keyword),
                            equal("metadata.name", keyword))));

            Optional.ofNullable(getRole())
                    .filter(StringUtils::isNotBlank)
                    .ifPresent(role -> builder.andQuery(in(User.USER_RELATED_ROLES_INDEX, role)));

            return builder.build();
        }

        public static void buildParameters(Builder builder) {
            SortableRequest.buildParameters(builder);
            builder.parameter(parameterBuilder()
                            .in(ParameterIn.QUERY)
                            .name("keyword")
                            .description("Keyword to search")
                            .implementation(String.class)
                            .required(false))
                    .parameter(parameterBuilder()
                            .in(ParameterIn.QUERY)
                            .name("role")
                            .description("Role metadata.name")
                            .implementation(String.class)
                            .required(false));
        }
    }

    record ListedUser(
            @Schema(requiredMode = REQUIRED) User user,
            @Schema(requiredMode = REQUIRED) List<Role> roles) {}
}

