                .when(validator)
                .validate(any(), any());
        webClient
                .post()
                .uri("/users/-/send-email-verification-code")
                .contentType(MediaType.APPLICATION_JSON)
                .bodyValue(Map.of("email", "invalid"))
                .exchange()
                .expectStatus()
                .isBadRequest()
                .expectBody()
                .jsonPath("$.detail")
                .isEqualTo("邮箱格式不正确");
