            when(roleService.list(any())).thenReturn(Flux.empty());
            when(client.listBy(same(User.class), any(), any(PageRequest.class)))
                    .thenReturn(Mono.just(ListResult.emptyResult()));

            webClient
                    .get()
                    .uri("/users")
